package portfolio.capstone;
import javafx.application.Application; import javafx.application.Platform; import javafx.fxml.FXMLLoader; import javafx.scene.Scene; import javafx.stage.Stage; import java.util.concurrent.*;
public final class App extends Application { private ScheduledExecutorService scheduler; private MainController controller; public void start(Stage stage)throws Exception{FXMLLoader loader=new FXMLLoader(App.class.getResource("main-view.fxml"));stage.setScene(new Scene(loader.load(),1000,560));controller=loader.getController();stage.setTitle("University Management System");stage.show();scheduler=Executors.newSingleThreadScheduledExecutor();scheduler.scheduleAtFixedRate(()->Platform.runLater(controller::markRefresh),5,5,TimeUnit.SECONDS);} public void stop(){if(scheduler!=null)scheduler.shutdownNow();} public static void main(String[]a){launch(a);} }
